#!/usr/bin/env bash
# SPDX-FileCopyrightText: 2026 Accemic Technologies GmbH
# SPDX-License-Identifier: ISC
#
# Reproducibly restore the pinned upstream core sources that the
# CVA6-family KV260 examples (cva6_linux, cva6_linux64, cva6_2) build
# against. Pin details + rationale: ./CVA6_PIN.md and ./ROCKET_PIN.md.
#
# Scope: this script only handles cva6_ref (a plain git-clonable pinned
# dependency). rocket_ref is a GENERATED Chisel/FIRRTL Verilog blob, not a
# tree this script can "clone" into place -- see the "Generation" section
# of ROCKET_PIN.md for the WSL2/sbt recipe that produced it. The
# rocket_linux/rocket2 examples do not vendor or fetch rocket_ref here;
# their RTL (rocket_soc_synth_wrap.sv etc.) instantiates the RocketSystem
# top by name and expects it to be elaborated/synthesized alongside the
# generated system-nexys-video.v (or the rocket64t2 two-hart generat for
# rocket2), obtained separately per ROCKET_PIN.md.
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"

CVA6_URL="https://github.com/openhwgroup/cva6"
CVA6_PIN="a3dc2c5e7835b25dc8437eee3e956ab12857ead7"
cva6_dest="$here/cva6_ref"

pin_checkout() {   # <url> <pin> <dest> <label>
    local url="$1" pin="$2" d="$3" label="$4"
    if [ -d "$d/.git" ]; then
        echo "[fetch] $label already present -- fetch + checkout to pin"
        git -C "$d" fetch --quiet origin
    else
        echo "[fetch] clone $url -> $d"
        git clone --quiet "$url" "$d"
    fi
    git -C "$d" checkout --quiet "$pin"
    # The CVA6 upstream carries its PULP infrastructure (axi, common_cells,
    # fpga-support, ...) as git submodules under vendor/. Without them the
    # bitstream flow dies with "### ERROR missing: .../vendor/pulp-..." --
    # found the expensive way on the first fresh-fetch build (2026-08-17).
    git -C "$d" submodule update --init --depth 1 --quiet 2>/dev/null ||         git -C "$d" submodule update --init --quiet
    # Local adjustment the flows depend on: upstream common_cells ships
    # counter.sv, but the encoder tree brings its OWN `counter` module with a
    # different port list -- both in one Vivado project is a name clash. The
    # original integration solved it by carrying counter.sv under the module
    # name pulp_counter (and the flist call excludes counter.sv); reproduce
    # that here so a fresh fetch builds without hand work.
    cc="$d/vendor/pulp-platform/common_cells/src"
    if [ -f "$cc/counter.sv" ] && [ ! -f "$cc/pulp_counter.sv" ]; then
        sed -e 's/module counter/module pulp_counter/' \n            -e 's/endmodule : counter/endmodule : pulp_counter/' \n            "$cc/counter.sv" > "$cc/pulp_counter.sv"
        # Say in the file itself that it is generated. Without this a reader
        # who finds pulp_counter.sv in the vendored tree has no way to tell
        # it apart from upstream material -- and any header edited into it
        # by hand is silently lost on the next fetch, because this branch
        # rewrites the file from counter.sv every time it is missing.
        printf '%s\n' \
            "// SPDX-FileCopyrightText: 2026 Accemic Technologies GmbH" \
            # REUSE-IgnoreStart -- the next line is a header this script WRITES
            # into a vendored file, not a licence statement about fetch.sh.
            "// SPDX-License-Identifier: SHL-0.51" \
            # REUSE-IgnoreEnd
            "//" \
            "// GENERATED by examples/kv260/third_party/fetch.sh -- do not edit." \
            "// Source: vendor/pulp-platform/common_cells/src/counter.sv," \
            "// module and endmodule label renamed to pulp_counter. Delta D7 in" \
            "// CVA6_PIN.md: the encoder tree brings its own \`counter\` with a" \
            "// different port list, and both in one Vivado project is a name" \
            "// clash (Synth 8-7136). Edits here do not survive the next fetch." \
            "" \
            > "$cc/pulp_counter.sv.hdr"
        cat "$cc/pulp_counter.sv" >> "$cc/pulp_counter.sv.hdr"
        mv "$cc/pulp_counter.sv.hdr" "$cc/pulp_counter.sv"
        echo "[fetch] $label: staged counter.sv as pulp_counter.sv (name-clash rename, delta D7)"
    fi
    # The two PULP axi consumers in the bitstream file lists instantiate
    # `counter #(...)` and would elaborate against CTTE's own counter
    # (different ports -> Synth 8-7136, cva6_linux bitgen run 8). An earlier
    # vendored tree carried them patched to pulp_counter; reproduce that
    # consumer half of the delta too (idempotent). Documented as D7 in
    # CVA6_PIN.md -- deliberately a sed and not a patch file, because a
    # context diff would break on every upstream bump while this expression
    # survives it.
    local axisrc="$d/vendor/pulp-platform/axi/src"
    for f in axi_err_slv.sv axi_burst_splitter.sv; do
        if [ -f "$axisrc/$f" ] && grep -qE '(^|[^_a-zA-Z0-9])counter #' "$axisrc/$f"; then
            sed -i -E 's/(^|[^_a-zA-Z0-9])counter #/pulp_counter #/' "$axisrc/$f"
            echo "[fetch] $label: retargeted $f counter -> pulp_counter"
        fi
    done
    # The local deltas D1..D6 that CVA6_PIN.md documents (trap visibility,
    # interrupt priority, TechnoCut, MMU clamp, KV260 address regions, XSIM
    # guard) plus the additional RV64 config. Until 2026-08-17 the pin file
    # DESCRIBED them and nothing applied them: the freshly fetched tree built
    # a clean bitstream whose CVA6 took an Instruction Access Fault on its
    # very first fetch (D5 missing -- execute region still pointed at the
    # Genesys2 DRAM). A documented delta that no script applies is a trap,
    # not documentation. `patch -N` keeps this idempotent on re-runs.
    local pdir="$here/patches/cva6"
    if [ -d "$pdir" ]; then
        local p
        for p in "$pdir"/0*.patch; do
            if patch -d "$d" -p1 -N -s --dry-run < "$p" >/dev/null 2>&1; then
                patch -d "$d" -p1 -N -s < "$p"
                echo "[fetch] $label: applied $(basename "$p")"
            elif patch -d "$d" -p1 -R -s --dry-run < "$p" >/dev/null 2>&1; then
                : # already applied (reverse applies cleanly)
            else
                echo "[fetch] $label: PATCH FAILED $(basename "$p") -- pin/patch drift" >&2
                exit 3
            fi
        done
        cp "$pdir/cv64a6_imac_sv39_ctrace_config_pkg.sv" "$d/core/include/"
    fi
    local got
    got="$(git -C "$d" rev-parse HEAD)"
    if [ "$got" != "$pin" ]; then
        echo "[fetch] ERROR: $label HEAD=$got != pin=$pin" >&2
        exit 1
    fi
    echo "[fetch] OK -- $label @ $pin"
}

pin_checkout "$CVA6_URL" "$CVA6_PIN" "$cva6_dest" "cva6_ref"

echo "[fetch] initializing cva6_ref submodules (core/cvfpu, core/cache_subsystem/hpdcache)"
git -C "$cva6_dest" submodule update --init --recursive \
    core/cvfpu core/cache_subsystem/hpdcache

echo "[fetch] NOTE: this is the upstream tree WITH the local RTL deltas"
echo "[fetch]       applied -- six patches in patches/cva6/ (D1/D2/D4"
echo "[fetch]       upstream-worthy fixes, D3/D5/D6 KV260-specific"
echo "[fetch]       configuration), documented in CVA6_PIN.md. Nothing to"
echo "[fetch]       apply by hand; the applied names are listed above."
echo "[fetch]       (Until 2026-08-21 this note claimed the opposite and"
echo "[fetch]       counted four -- while the body already applied all six.)"
echo "[fetch]"
echo "[fetch] rocket_ref: NOT fetched by this script -- see ROCKET_PIN.md"
echo "[fetch]             'Generation (reproducible)' for the WSL2/sbt recipe."
echo "[fetch] cva6_ref:   $cva6_dest"
